#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>
#include <sys/mount.h>
#include <unistd.h>

// Note: MNT_DETACH is specific to Linux headers, often defined
// in <sys/mount.h>. If compiling on older systems, it might need definition.
#ifndef MNT_DETACH
#define MNT_DETACH 0x00000004
#endif

int main(int argc, char *argv[]) {
    // Must be run as root (or with CAP_SYS_ADMIN) and target must be a mount point.
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <target_mount_point>\n", argv[0]);
        return EXIT_FAILURE;
    }
    const char *target = argv[1];
    int result;

    printf("Attempting lazy unmount (MNT_DETACH) for: %s\n", target);

    // Use umount2 with MNT_DETACH for immediate logical disconnection.
    result = umount2(target, MNT_DETACH);

    if (result == -1) {
        if (errno == EPERM) {
            fprintf(stderr, "Error: Permission denied. Requires root/CAP_SYS_ADMIN.\n");
        } else if (errno == EINVAL) {
            fprintf(stderr, "Error: %s is not a valid mount point or flags are invalid.\n", target);
        } else if (errno == EBUSY) {
             fprintf(stderr, "Error: Filesystem is busy, and MNT_DETACH failed unexpectedly.\n");
        } else {
            perror("umount2 failed");
        }
        return EXIT_FAILURE;
    }

    printf("Successfully initiated lazy unmount of %s. Actual unmount deferred until unused.\n", target);

    return EXIT_SUCCESS;
}
